import requests, json, sys

webhook_url = "https://open.feishu.cn/open-apis/bot/v2/hook/608c82a6-6355-4bcb-b0b0-5c097602d2c9"

news = [
    {
        "title": "Agent落地与AI编程革命",
        "summary": "2025年大模型Agent实现自主规划与跨系统集成，Claude等AI编程模型表现优异，2026年将迎来企业级应用爆发。",
        "source": "CSDN",
        "date": "2026-03-31"
    },
    {
        "title": "消费级AI应用爆发元年到来",
        "summary": "a16z预测2026年迎来消费级AI应用爆发，ChatGPT周活达8-9亿，大模型从文本对话转向全模态实时交互。",
        "source": "CSDN",
        "date": "2025-12-31"
    },
    {
        "title": "AI应用商业化明显加速",
        "summary": "字节豆包日Tokens突破50万亿同比增长超10倍，千问APP成全球增长最快AI应用，超级AI入口与垂类应用并行发展。",
        "source": "腾讯网/财联社",
        "date": "2025-12-29"
    },
    {
        "title": "2026大模型技术全面展望",
        "summary": "多模态大模型全面突破，DeepSeek R1开源推理领先，国产芯片与一体机大幅降低部署成本。",
        "source": "CSDN",
        "date": "2025-12-08"
    },
    {
        "title": "大模型参数跃升至千亿级",
        "summary": "模型参数从百亿跃升至千亿级，上下文窗口中位数达128K，最大闭源模型达200万，RLVR技术显著提升推理能力。",
        "source": "搜狐/中国工业互联网研究院",
        "date": "2025-05-13"
    },
    {
        "title": "天玑9400+智能体AI芯片发布",
        "summary": "MediaTek发布旗舰5G智能体AI芯片，NPU支持MoE/MLA/FP8推理加速，AI任务推理速度提升20%。",
        "source": "CSDN",
        "date": "2025-04-17"
    },
    {
        "title": "AI工具生态全面繁荣",
        "summary": "Microsoft 365 Copilot深度融合办公套件，ChatGPT-5多模态能力出色，AI绘画与写作工具快速普及。",
        "source": "PHP中文网",
        "date": "2025-04-10"
    },
    {
        "title": "Gemini 2.5 Pro登顶LMArena",
        "summary": "谷歌DeepMind推出最智能AI模型Gemini 2.5 Pro，在数学、科学及编码测试中表现突出，SWE-Bench得分63.8%。",
        "source": "CSDN",
        "date": "2025-03-26"
    },
    {
        "title": "AI芯片与云计算基础设施持续加码",
        "summary": "中证芯片产业指数上涨2.3%，全球AI基础设施投资不断加码，AI生成内容市场预计2026年突破500亿美元。",
        "source": "搜狐/每日经济新闻",
        "date": "2025-03-04"
    },
    {
        "title": "中国AI算力规模两年翻番",
        "summary": "IDC报告显示2025年中国智能算力达1037.3 EFLOPS同比增长43%，DeepSeek低成本高性能获国际认可。",
        "source": "今日头条/IDC",
        "date": "2025-02-19"
    }
]

# Build card elements
elements = []
for i, item in enumerate(news):
    # News content
    elements.append({
        "tag": "div",
        "fields": [{
            "is_short": False,
            "text": {
                "tag": "lark_md",
                "content": f"**{i+1}. {item['title']}**\n{item['summary']}\n来源：{item['source']} | {item['date']}"
            }
        }]
    })
    # Divider (except after last item)
    if i < len(news) - 1:
        elements.append({"tag": "hr"})

card = {
    "config": {"wide_screen_mode": True},
    "header": {
        "title": {
            "tag": "plain_text",
            "content": "AI 产品/技术日报 | 2026年6月1日"
        },
        "template": "green"
    },
    "elements": elements,
    "note": {
        "tag": "plain_text",
        "content": "由 Incaier Agent 自动生成"
    }
}

payload = {
    "msg_type": "interactive",
    "card": card
}

resp = requests.post(webhook_url, json=payload, timeout=15)
result = {"status_code": resp.status_code, "body": resp.json()}
with open(sys.argv[-1], 'w', encoding='utf-8') as f:
    json.dump(result, f, ensure_ascii=False, indent=2)
print(json.dumps(result, ensure_ascii=False, indent=2))

